private static String TAG = "RNCWebViewClient";
private volatile boolean porticoReaderSurface = false;

@Override
public WebResourceResponse shouldInterceptRequest(WebView view, WebResourceRequest request) {
    String url = request.getUrl().toString();
    if (PorticoReaderAndroidAssets.isEntry(url)) porticoReaderSurface = true;
    if (porticoReaderSurface || PorticoReaderAndroidAssets.isOrigin(url))
        return PorticoReaderAndroidAssets.response(view.getContext(), request);
    return super.shouldInterceptRequest(view, request);
}
